const nav = [['/espace', 'Vue d’ensemble', LayoutDashboard], ['/calendrier', 'Calendrier', CalendarDays], ['/eleves', 'Élèves', Users], ['/demandes', 'Demandes', Inbox], ['/evaluations', 'Évaluations', ClipboardList], ['/documents', 'Documents', FileText], ['/attente', 'Liste d’attente', Clock], ['/avis', 'Avis', Star], ['/parametres', 'Paramètres', Settings]] as const;
